const fs = require("fs");
const path = require("path");

const bashHeaders = ["#!/usr/bin/env", "#!/bin/sh"];
const rushPreHeader =
  "// THIS FILE WAS GENERATED BY A TOOL. ANY MANUAL MODIFICATIONS WILL GET OVERWRITTEN WHENEVER RUSH IS UPGRADED.";

function buildLicensedText(licenseContent, options = {}) {
  const { commentLinePrefix = "// ", commentPrefix, commentSuffix } = options;

  return (
    (commentPrefix ? commentPrefix + "\n" : "") +
    licenseContent
      .split("\n")
      .map((line) => commentLinePrefix + line)
      .join("\n") +
    (commentSuffix ? "\n" + commentSuffix : "") +
    "\n\n"
  );
}

function normalizeLineEndings(content) {
  return content.replace(/\r\n?/g, "\n");
}

function hasExistingHeader(originalContent, licensedText) {
  const normalizedContent = normalizeLineEndings(originalContent);
  const normalizedLicensedText = normalizeLineEndings(licensedText).trim();
  const shebangMatch = normalizedContent.match(/^#![^\n]*(?:\n|$)/);
  const contentAfterShebang = shebangMatch
    ? normalizedContent.slice(shebangMatch[0].length)
    : normalizedContent;

  return (
    normalizedContent.startsWith(normalizedLicensedText) ||
    contentAfterShebang.startsWith(normalizedLicensedText) ||
    bashHeaders.some((header) => normalizedContent.startsWith(header)) ||
    normalizedContent.startsWith(rushPreHeader)
  );
}

function processFile(filePath, licensedText, options = {}) {
  const { includeExts = [], force = false } = options;
  const ext = path.extname(filePath).toLowerCase();
  if (includeExts.length > 0 && !includeExts.includes(ext)) {
    return false;
  }

  try {
    const originalContent = fs.readFileSync(filePath, "utf8");

    if (!force && hasExistingHeader(originalContent, licensedText)) {
      return false;
    }

    const shebangMatch = originalContent.match(/^#![^\n]*(?:\n|$)/);
    const fileLicensedText = originalContent.includes("\r\n")
      ? licensedText.replace(/\n/g, "\r\n")
      : licensedText;
    const shebangLine = shebangMatch?.[0];
    const separator = shebangLine && !/[\r\n]$/.test(shebangLine) ? "\n" : "";
    const newContent = shebangLine
      ? shebangLine +
        separator +
        fileLicensedText +
        originalContent.slice(shebangLine.length)
      : fileLicensedText + originalContent;

    fs.writeFileSync(filePath, newContent, "utf8");
    console.log(
      `[Success] License added: ${filePath}, please manually upload the locally modified file`
    );
    return true;
  } catch (err) {
    console.error(`[ERROR] Failed to process file ${filePath}:`, err.message);
    return false;
  }
}

function addLicenseHeader(targetDir, licenseContent, options = {}) {
  const {
    includeExts = [".js", ".ts", ".mjs", ".cjs", ".html", ".css", ".scss"],
  } = options;
  const ig = require("ignore")();
  const ignorePaths = [
    ".next",
    "doc_build",
    "apps/docs/components/free-examples",
    "apps/docs/components/fixed-examples",
  ];
  const ignoreFile = fs.readFileSync(path.join(targetDir, ".gitignore"), {
    encoding: "utf-8",
  });
  ig.add(ignoreFile);
  ig.add(ignorePaths);

  const licensedText = buildLicensedText(licenseContent, options);

  function traverseDir(currentDir) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);

      if (ig.ignores(path.relative(targetDir, fullPath))) {
        continue;
      }

      if (entry.isDirectory()) {
        traverseDir(fullPath);
      } else {
        processFile(fullPath, licensedText, { ...options, includeExts });
      }
    }
  }

  if (fs.existsSync(targetDir) && fs.statSync(targetDir).isDirectory()) {
    traverseDir(targetDir);
    console.log("License Header add successfully");
  } else {
    console.error("Error: The destination path is not a valid folder");
  }
}

module.exports = {
  addLicenseHeader,
  buildLicensedText,
  hasExistingHeader,
  processFile,
};
